-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.premium_metrics
COMMENT 'Premium administration KPIs over premium movements - written premium, insurance premium tax collected, commission paid and the commission ratio, by line, period and currency. Earned premium and the written=earned+unearned proof live in the premium_earning view and vw_premium_proof. Amounts are in original currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_policy.premium_transaction

joins:
  - name: policy
    source: lr_serverless_aws_us_catalog.bricksurance_policy.policy
    on: source.policy_id = policy.policy_id

dimensions:
  - name: transaction_month
    expr: DATE_TRUNC('MONTH', source.transaction_date)
  - name: premium_transaction_type_code
    expr: source.premium_transaction_type_code
  - name: line_of_business_code
    expr: policy.line_of_business_code
  - name: currency_code
    expr: source.currency_code

measures:
  - name: gross_written_premium
    expr: SUM(amount)
  - name: ipt_collected
    expr: SUM(ipt_amount)
  - name: commission_total
    expr: SUM(commission_amount)
  - name: commission_ratio
    expr: SUM(commission_amount) / NULLIF(SUM(amount), 0)
$$;
